// One entry per reference: the matching shipments (id, reference, status) or "not found".
const refs = $('One item per reference').all().map(i => i.json);
const results = $input.all().map((item, i) => {
  let parsed;
  try { parsed = JSON.parse(item.json.body || '[]'); } catch (e) { parsed = []; }
  const list = Array.isArray(parsed) ? parsed : (parsed.results || parsed.items || parsed.shipments || []);
  const matches = list.slice(0, 5).map(s => ({
    id: s.id, reference: s.reference || s.name || null, status: s.status || null, eta: s.eta || null,
  }));
  return { ...refs[i], found: matches.length > 0, matches };
});
return [{ json: { results } }];

// Gmail returns base64url; Convert to File expects standard base64.
return $input.all().map((item, i) => {
  const att = $('One item per attachment').itemMatching(i).json;
  return { json: { data: item.json.data.replace(/-/g, '+').replace(/_/g, '/'), filename: att.filename, mime: att.mime } };
});
